"use client";

import { useId, useState } from "react";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { CHART_THEMES } from "@/lib/chart-themes";
import { cn } from "@/lib/utils";
import {
  formatRadarValue,
  radarCeiling,
  summarizeRadarChart,
} from "@/features/radar-chart/radar-chart-schema";
import type { RadarChartData } from "@/features/radar-chart/radar-chart-schema";

export type RadarChartCardState = "streaming" | "loading" | "ready" | "error";

export interface RadarChartCardProperties {
  readonly state: RadarChartCardState;
  /**
  The topic from the tool input, shown before the data arrives.
  */
  readonly topic?: string;
  readonly data?: RadarChartData;
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-md`;

function titleCase(value: string) {
  return value
    .trim()
    .split(/\s+/u)
    .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(" ");
}

/**
The web in chart units: the center, and the radius of its outer ring. The labels sit outside it, so it leaves room round the edge.
*/
const VIEW = 200;
const CENTER = VIEW / 2;
const RADIUS = 72;
const LABEL_RADIUS = RADIUS + 10;

/**
The rings drawn inside the web, as fractions of the outer one.
*/
const RINGS = [0.25, 0.5, 0.75, 1] as const;
const HATCH_GAP = 4;

/**
How each subject's shape is drawn. The first is the subject of the question, in the card's own teal (every chart card has its own color) with hatching; the others are outlines in ink, dashed and dotted like a printed chart, so they stay apart without more colors.
*/
const SERIES_STYLES = [
  { dash: null, tone: CHART_THEMES.radar.solid },
  { dash: "5 3", tone: "text-foreground/75" },
  { dash: "1 3.5", tone: "text-muted-foreground" },
] as const;

/**
How long each subject's shape waits after the one before it to grow out of the center.
*/
const SERIES_STAGGER_MS = 160;

function angleOf(index: number, count: number) {
  return -Math.PI / 2 + (index / count) * Math.PI * 2;
}

function pointAt(index: number, count: number, radius: number) {
  const angle = angleOf(index, count);
  return [
    CENTER + Math.cos(angle) * radius,
    CENTER + Math.sin(angle) * radius,
  ] as const;
}

function polygon(radii: readonly number[]) {
  return radii
    .map((radius, index) => pointAt(index, radii.length, radius).join(","))
    .join(" ");
}

/**
How a label hangs off its spoke's end: centered over the top and bottom spokes, pushed out to the side on the others, so no label crosses the web.
*/
function labelPlacement(index: number, count: number) {
  const angle = angleOf(index, count);
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const SIDEWAYS = 0.2;
  const UPRIGHT = 0.5;
  return cn(
    Math.abs(cos) < SIDEWAYS && "-translate-x-1/2 items-center text-center",
    cos >= SIDEWAYS && "items-start text-left",
    cos <= -SIDEWAYS && "-translate-x-full items-end text-right",
    sin < -UPRIGHT && "-translate-y-full",
    Math.abs(sin) <= UPRIGHT && "-translate-y-1/2"
  );
}

function formatAxisValue(
  data: RadarChartData,
  seriesIndex: number,
  axisIndex: number
) {
  const value = data.series[seriesIndex]?.values[axisIndex];
  return value === null || value === undefined
    ? "—"
    : formatRadarValue(value, data.scale);
}

const SeriesShape = ({
  data,
  seriesIndex,
  ceiling,
  isDimmed,
  hatchId,
}: {
  readonly data: RadarChartData;
  readonly seriesIndex: number;
  readonly ceiling: number;
  readonly isDimmed: boolean;
  readonly hatchId: string;
}) => {
  const series = data.series[seriesIndex];
  const style = SERIES_STYLES[seriesIndex] ?? SERIES_STYLES[0];
  const count = data.axes.length;
  const radii = data.axes.map(
    (_, index) =>
      (Math.min(series.values[index] ?? 0, ceiling) / ceiling) * RADIUS
  );
  const shape = polygon(radii);
  const isLead = seriesIndex === 0;
  return (
    <g
      className={cn(
        "animate-in fade-in zoom-in-0 fill-mode-both origin-center transition-opacity duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:animate-none",
        style.tone,
        isDimmed && "opacity-20"
      )}
      style={{ animationDelay: `${seriesIndex * SERIES_STAGGER_MS}ms` }}
    >
      {isLead ? (
        <>
          <polygon points={shape} fill="currentColor" fillOpacity={0.1} />
          <polygon points={shape} fill={`url(#${hatchId})`} opacity={0.5} />
        </>
      ) : (
        <polygon points={shape} fill="currentColor" fillOpacity={0.04} />
      )}
      <polygon
        points={shape}
        fill="none"
        stroke="currentColor"
        strokeWidth={isLead ? 2 : 1.5}
        strokeDasharray={style.dash ?? undefined}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      {radii.map((radius, index) => {
        if (series.values[index] === null) {
          return null;
        }
        const [x, y] = pointAt(index, count, radius);
        return (
          <circle
            // One dot per axis, in the axes' fixed order.
            key={data.axes[index]}
            cx={x}
            cy={y}
            r={isLead ? 3 : 2.25}
            fill="currentColor"
            className="stroke-background"
            strokeWidth={1.5}
          />
        );
      })}
    </g>
  );
};

const Web = ({
  data,
  activeSeries,
}: {
  readonly data: RadarChartData;
  readonly activeSeries: number | null;
}) => {
  const hatchId = useId();
  const [activeAxis, setActiveAxis] = useState<number | null>(null);
  const ceiling = radarCeiling(data);
  const count = data.axes.length;
  const isSingle = data.series.length === 1;

  return (
    <div className="relative mx-auto aspect-square w-full max-w-64">
      <svg
        aria-hidden
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className="size-full overflow-visible"
      >
        <defs>
          {/* A pattern takes its color from where it is defined, not from the
              shape that uses it, so it carries the lead subject's color. */}
          <pattern
            id={hatchId}
            className={SERIES_STYLES[0].tone}
            width={HATCH_GAP}
            height={HATCH_GAP}
            patternUnits="userSpaceOnUse"
            patternTransform="rotate(45)"
          >
            <line
              x1={0}
              y1={0}
              x2={0}
              y2={HATCH_GAP}
              stroke="currentColor"
              strokeWidth={1}
            />
          </pattern>
        </defs>
        {RINGS.map((ring) => (
          <polygon
            key={ring}
            points={polygon(data.axes.map(() => ring * RADIUS))}
            fill="none"
            className={ring === 1 ? "stroke-foreground/25" : "stroke-border"}
            strokeDasharray={ring === 1 ? undefined : "2 3"}
          />
        ))}
        {data.axes.map((axis, index) => {
          const [x, y] = pointAt(index, count, RADIUS);
          return (
            <line
              key={axis}
              x1={CENTER}
              y1={CENTER}
              x2={x}
              y2={y}
              className={cn(
                "transition-colors duration-200",
                activeAxis === index ? "stroke-foreground/60" : "stroke-border"
              )}
            />
          );
        })}
        {data.series.map((series, seriesIndex) => (
          <SeriesShape
            key={series.name}
            data={data}
            seriesIndex={seriesIndex}
            ceiling={ceiling}
            hatchId={hatchId}
            isDimmed={activeSeries !== null && activeSeries !== seriesIndex}
          />
        ))}
      </svg>

      {/* The scale up the top spoke: half and full. */}
      {[0.5, 1].map((ring) => (
        <span
          key={ring}
          aria-hidden
          className="text-muted-foreground bg-background pointer-events-none absolute translate-x-1.5 -translate-y-1/2 rounded-[2px] px-0.5 font-mono text-[10px] leading-3 tabular-nums"
          style={{
            left: "50%",
            top: `${((CENTER - ring * RADIUS) / VIEW) * 100}%`,
          }}
        >
          {formatRadarValue(ring * ceiling, data.scale)}
        </span>
      ))}

      {data.axes.map((axis, index) => {
        const [x, y] = pointAt(index, count, LABEL_RADIUS);
        const isTop = y < CENTER;
        return (
          <div
            key={axis}
            aria-hidden
            className={cn(
              "group/axis absolute flex flex-col",
              labelPlacement(index, count)
            )}
            style={{
              left: `${(x / VIEW) * 100}%`,
              top: `${(y / VIEW) * 100}%`,
            }}
            onMouseEnter={() => setActiveAxis(index)}
            onMouseLeave={() => setActiveAxis(null)}
          >
            <span className="text-muted-foreground group-hover/axis:text-foreground max-w-24 truncate text-xs leading-4 transition-colors">
              {axis}
            </span>
            {isSingle ? (
              <span className="font-mono text-xs leading-4 font-medium tabular-nums">
                {formatAxisValue(data, 0, index)}
              </span>
            ) : (
              <span
                className={cn(
                  "bg-popover text-popover-foreground pointer-events-none absolute left-1/2 z-10 hidden min-w-max -translate-x-1/2 flex-col gap-0.5 rounded-sm border px-2 py-1 text-xs shadow-sm group-hover/axis:flex",
                  isTop ? "bottom-full mb-1" : "top-full mt-1"
                )}
              >
                {data.series.map((series, seriesIndex) => (
                  <span key={series.name} className="flex items-center gap-2">
                    <span
                      className={cn(
                        "size-1.5 rounded-full bg-current",
                        SERIES_STYLES[seriesIndex]?.tone
                      )}
                    />
                    <span className="text-muted-foreground">{series.name}</span>
                    <span className="ml-auto pl-2 font-mono font-semibold tabular-nums">
                      {formatAxisValue(data, seriesIndex, index)}
                    </span>
                  </span>
                ))}
              </span>
            )}
          </div>
        );
      })}
    </div>
  );
};

/**
The key: each subject with a sample of its line. Hovering one brings its shape forward.
*/
const Legend = ({
  data,
  onActive,
}: {
  readonly data: RadarChartData;
  readonly onActive: (index: number | null) => void;
}) => (
  <ul className="flex flex-wrap items-center justify-center gap-x-4 gap-y-1">
    {data.series.map((series, index) => {
      const style = SERIES_STYLES[index] ?? SERIES_STYLES[0];
      return (
        <li key={series.name}>
          <button
            type="button"
            className="focus-visible:ring-ring flex h-5 cursor-default items-center gap-1.5 rounded-sm text-xs outline-none focus-visible:ring-2"
            onMouseEnter={() => onActive(index)}
            onMouseLeave={() => onActive(null)}
            onFocus={() => onActive(index)}
            onBlur={() => onActive(null)}
          >
            <svg
              aria-hidden
              viewBox="0 0 16 4"
              className={cn("h-1 w-4", style.tone)}
            >
              <line
                x1={1}
                y1={2}
                x2={15}
                y2={2}
                stroke="currentColor"
                strokeWidth={2}
                strokeDasharray={style.dash ?? undefined}
                strokeLinecap="round"
              />
            </svg>
            <span className={cn(index === 0 && "font-semibold")}>
              {series.name}
            </span>
          </button>
        </li>
      );
    })}
  </ul>
);

/**
The figures as a table for screen readers, since the web itself is a picture.
*/
const DataTable = ({ data }: { readonly data: RadarChartData }) => (
  <table className="sr-only">
    <caption>{data.label}</caption>
    <thead>
      <tr>
        <th scope="col">Measure</th>
        {data.series.map((series) => (
          <th key={series.name} scope="col">
            {series.name}
          </th>
        ))}
      </tr>
    </thead>
    <tbody>
      {data.axes.map((axis, axisIndex) => (
        <tr key={axis}>
          <th scope="row">{axis}</th>
          {data.series.map((series, seriesIndex) => (
            <td key={series.name}>
              {formatAxisValue(data, seriesIndex, axisIndex)}
            </td>
          ))}
        </tr>
      ))}
    </tbody>
  </table>
);

const RadarChartReady = ({ data }: { readonly data: RadarChartData }) => {
  const [activeSeries, setActiveSeries] = useState<number | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <header className="flex h-5 min-w-0 items-center">
        <p className="truncate text-sm font-semibold">
          {titleCase(data.topic)}
        </p>
      </header>

      <div className="px-10 py-6">
        <Web data={data} activeSeries={activeSeries} />
      </div>

      {data.series.length > 1 ? (
        <Legend data={data} onActive={setActiveSeries} />
      ) : null}

      <DataTable data={data} />

      <footer className="flex items-center justify-between gap-2">
        <p className="text-muted-foreground min-w-0 truncate text-xs">
          {data.label}
        </p>
      </footer>
    </div>
  );
};

const RadarChartError = ({
  topic,
  message = "The figures service didn't respond. Try again in a moment.",
}: {
  readonly topic?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {topic
        ? `Couldn't load a comparison of ${titleCase(topic)}`
        : "Couldn't load the radar chart"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

const SKELETON_AXES = 6;

/**
The card while its data is on the way: an empty web the size of the ready one, so the card holds its place while the figures are found. Shows the topic as soon as it's known (with "…" while the model is still writing it).
*/
export const RadarChartCardSkeleton = ({
  topic,
  streaming = false,
  className,
}: {
  readonly topic?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "flex flex-col gap-3", className)}>
    <span className="sr-only">
      {topic ? `Loading a comparison of ${topic}` : "Loading a radar chart"}
    </span>
    <div aria-hidden className="flex h-5 items-center">
      {topic ? (
        <p className="truncate text-sm font-semibold">
          {titleCase(topic)}
          {streaming ? <span className="text-muted-foreground">…</span> : null}
        </p>
      ) : (
        <div className="bg-muted h-3.5 w-24 animate-pulse rounded" />
      )}
    </div>
    <div aria-hidden className="px-10 py-6">
      <svg
        aria-hidden
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className="mx-auto aspect-square w-full max-w-64 animate-pulse"
      >
        {RINGS.map((ring) => (
          <polygon
            key={ring}
            points={polygon(
              Array.from({ length: SKELETON_AXES }, () => ring * RADIUS)
            )}
            fill="none"
            className="stroke-muted"
            strokeWidth={ring === 1 ? 2 : 1}
          />
        ))}
      </svg>
    </div>
    <div aria-hidden className="flex h-4 items-center">
      <div className="bg-muted h-3 w-24 animate-pulse rounded" />
    </div>
  </output>
);

export const RadarChartCard = ({
  state,
  topic,
  data,
  error,
  className,
}: RadarChartCardProperties) => {
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <RadarChartError topic={topic} message={error} />
      </div>
    );
  }
  if (state !== "ready" || !data) {
    return (
      <RadarChartCardSkeleton
        topic={topic}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  return (
    <section
      aria-label={summarizeRadarChart(data)}
      className={cn(CARD_FRAME, className)}
    >
      <RadarChartReady data={data} />
    </section>
  );
};

"use client";

import { useEffect, useState } from "react";
import { RadarChartCard } from "@/features/radar-chart/components/radar-chart-card";
import { loadRadarChart } from "@/features/radar-chart/radar-chart-requests";
import type { RadarChartData } from "@/features/radar-chart/radar-chart-schema";

/**
What came back for one request. A result for a different topic reads as still loading, so a new topic never flashes the old chart.
*/
type Result =
  | { key: string; status: "ready"; data: RadarChartData }
  | { key: string; status: "error"; message: string };

export const LiveRadarChartCard = ({
  topic,
  streaming = false,
}: {
  readonly topic?: string;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [result, setResult] = useState<Result | null>(null);
  const requestKey = topic ?? "";

  useEffect(() => {
    let isCancelled = false;
    const run = async (wanted: string) => {
      let next: Result;
      try {
        next = {
          data: await loadRadarChart(wanted),
          key: requestKey,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: requestKey,
          message: Error.isError(error) ? error.message : "Radar chart failed.",
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && topic) {
      run(topic);
    }
    return () => {
      isCancelled = true;
    };
  }, [topic, requestKey, streaming]);

  if (streaming || !topic) {
    return <RadarChartCard state="streaming" topic={topic} />;
  }
  const current = result?.key === requestKey ? result : null;
  if (current?.status === "ready") {
    return <RadarChartCard state="ready" data={current.data} />;
  }
  return current?.status === "error" ? (
    <RadarChartCard state="error" topic={topic} error={current.message} />
  ) : (
    <RadarChartCard state="loading" topic={topic} />
  );
};

import { z } from "zod";

export const radarChartCatalogEntry = {
  description: `A live radar (spider) chart for questions that profile one to three subjects across the same several measures on one shared scale ("compare the nutrition of an apple and a banana", "compare the top AI models on benchmarks", "iPhone vs Pixel camera scores"). Each axis is one measure and each subject is one shape. The model writes a free-text topic from the user's ask; the card researches the web and draws the web. The topic is the card's title, so keep it a short phrase naming the measures and the subjects ("Apple vs banana nutrition"). Never invent the numbers — the card fetches them. Not for one measure across many categories: that's BarChartCard. Not for parts of a whole: that's PieChartCard.`,
  props: z.object({
    topic: z
      .string()
      .describe(
        'The measures and the subjects, taken from the user\'s question — e.g. "apple vs banana nutrition" or "AI model benchmark scores".'
      ),
  }),
};

import type { RadarChartData } from "@/features/radar-chart/radar-chart-schema";

const sharedRadarChartRequests = new Map<
  string,
  { chart: Promise<RadarChartData>; expiresAt: number }
>();
const REUSE_MS = 120_000;

function cacheKey(topic: string) {
  return topic.trim().toLowerCase();
}

function radarChartUrl(topic: string) {
  const parameters = new URLSearchParams({ topic });
  return `/api/radar-chart?${parameters}`;
}

async function fetchRadarChart(topic: string) {
  const response = await fetch(radarChartUrl(topic));
  const body = (await response.json()) as RadarChartData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Radar chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestRadarChart(key: string, topic: string) {
  try {
    return await fetchRadarChart(topic);
  } catch (error) {
    sharedRadarChartRequests.delete(key);
    throw error;
  }
}

/**
Load a radar chart's figures. Shared, so the thinking steps and the card make one request between them.
*/
export function loadRadarChart(topic: string) {
  const key = cacheKey(topic);
  const hit = sharedRadarChartRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.chart;
  }
  const chart = requestRadarChart(key, topic);
  sharedRadarChartRequests.set(key, {
    chart,
    expiresAt: Date.now() + REUSE_MS,
  });
  return chart;
}

/**
Seed the client cache from a docs recording.
*/
export function primeRadarChart(topic: string, data: RadarChartData) {
  sharedRadarChartRequests.set(cacheKey(topic), {
    chart: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import { listOf } from "@/features/chat/lookup";
import { loadRadarChart } from "@/features/radar-chart/radar-chart-requests";
import { hostOf } from "@/lib/url-host";
import type { CardLookup, Source } from "@/features/chat/lookup";

function topicOf(properties: Record<string, unknown>): string {
  return typeof properties.topic === "string" ? properties.topic.trim() : "";
}

function researchSources(result: unknown): readonly Source[] {
  if (!result || typeof result !== "object") {
    return [];
  }
  const { sourceHref, sourceLabel } = result as {
    sourceHref?: unknown;
    sourceLabel?: unknown;
  };
  if (typeof sourceHref !== "string" || !sourceHref) {
    return [];
  }
  const label =
    typeof sourceLabel === "string" && sourceLabel.trim()
      ? sourceLabel.trim()
      : hostOf(sourceHref);
  return [{ href: sourceHref, label }];
}

export const radarChartLookup: CardLookup = {
  intent: (topics) =>
    topics.length === 1
      ? `A comparison of ${topics[0]}`
      : `Comparisons of ${listOf(topics)}`,
  load: (properties) => {
    const topic = topicOf(properties);
    return topic
      ? loadRadarChart(topic)
      : Promise.reject(
          new Error('Pass a topic, for example "apple vs banana nutrition".')
        );
  },
  resultSources: researchSources,
  sources: () => [
    {
      href: "https://parallel.ai",
      label: "parallel.ai",
    },
  ],
  subject: (properties) => topicOf(properties) || null,
};

import "server-only";
import {
  createExtractTool,
  createSearchTool,
} from "@parallel-web/ai-sdk-tools";
import { generateText, isStepCount, Output } from "ai";
import {
  MAX_AXES,
  MAX_SERIES,
  MIN_AXES,
  radarChartResultSchema,
} from "@/features/radar-chart/radar-chart-schema";
import type {
  RadarChartData,
  RadarChartResult,
  RadarSeries,
} from "@/features/radar-chart/radar-chart-schema";

/**
Research copies data tables into numbers, so it uses the same model as the other charts' research, separate from the chat model.
*/
const DEFAULT_RESEARCH_MODEL = "anthropic/claude-haiku-5.5";

/**
Tool steps before the model must answer. Step 0 is forced to search and step 1 to extract, so the numbers come from a page rather than memory; without a forced final answer the model keeps digging and returns nothing.
*/
const STEPS = 5;
const TIMEOUT_MS = 55_000;
/**
Parallel serves cached pages by default; an extracted page older than a day is fetched live so a table's newest release isn't missed.
*/
const LIVE_FETCH_MAX_AGE_S = 86_400;

export class RadarChartNotFoundError extends Error {
  constructor(topic: string, options?: ErrorOptions) {
    super(`No radar chart figures found for "${topic}".`, options);
    this.name = "RadarChartNotFoundError";
  }
}

function researchPrompt(topic: string): string {
  const today = new Date();
  const year = today.getUTCFullYear();

  return `Today is ${today.toISOString().slice(0, 10)}. Find real public figures that profile one to ${MAX_SERIES} subjects on the same set of measures, for a radar chart:

Topic: ${topic}

Requirements:
- ${MIN_AXES}–${MAX_AXES} measures (the axes), the same ones for every subject, all on one shared scale so they can sit on one web: benchmark percentages, percent of daily value, ratings out of 100.
- Never mix units across axes (dollars on one, percent on another); pick measures that share a scale.
- Prefer official or well-known sources (USDA FoodData Central, DXOMARK, published benchmark tables, national statistics offices).
- Search first, then extract the best URL(s) — a data table, CSV or JSON API, not an article — and copy the numbers from it.
- The latest edition, ${year - 1} or ${year} when it's published.
- max: the top of the scale when it has one (10 for 0–10, 100 for percent scores), otherwise null.
- Numeric values only; null for a measure the source has no figure for.
- You have ${STEPS} tool steps, then you must answer from what you extracted.
- If the topic can't be scored on shared measures, fail rather than inventing them.`;
}

/**
Drops a note the research model tacks on a name, like "Apple (raw, with skin)": the shape's label only has room for the name.
*/
function withoutNote(name: string): string {
  const trimmed = name.trim();
  const open = trimmed.indexOf(" (");
  return open > 0 && trimmed.endsWith(")") ? trimmed.slice(0, open) : trimmed;
}

function cleanAxes(axes: readonly string[]): string[] {
  return axes
    .map((axis) => axis.trim())
    .filter(Boolean)
    .slice(0, MAX_AXES);
}

function cleanSeries(
  series: RadarChartResult["series"],
  axisCount: number
): RadarSeries[] {
  const seen = new Set<string>();
  const cleaned: RadarSeries[] = [];
  for (const entry of series) {
    const name = withoutNote(entry.name);
    const values = Array.from({ length: axisCount }, (_, index) => {
      const value = entry.values[index];
      return typeof value === "number" && Number.isFinite(value) && value >= 0
        ? value
        : null;
    });
    if (
      !name ||
      seen.has(name.toLowerCase()) ||
      values.every((value) => value === null)
    ) {
      continue;
    }
    seen.add(name.toLowerCase());
    cleaned.push({ name, values });
  }
  return cleaned.slice(0, MAX_SERIES);
}

function toRadarChartData(
  query: string,
  output: RadarChartResult
): RadarChartData {
  const axes = cleanAxes(output.axes);
  const series = cleanSeries(output.series, axes.length);
  if (axes.length < MIN_AXES || series.length === 0) {
    throw new RadarChartNotFoundError(query);
  }
  return {
    asOf: Date.now(),
    axes,
    fake: false,
    label: output.label.trim() || "Score",
    max: output.max && output.max > 0 ? output.max : null,
    scale: output.scale,
    series,
    sourceHref: output.sourceHref ?? undefined,
    sourceLabel: output.sourceLabel ?? undefined,
    topic: query,
  };
}

async function researchOnce(
  query: string,
  abortSignal: AbortSignal
): Promise<RadarChartData> {
  const model = process.env.RADAR_CHART_MODEL || DEFAULT_RESEARCH_MODEL;
  const webSearch = createSearchTool({
    client_model: model,
    max_results: 8,
    mode: "advanced",
  });
  const webExtract = createExtractTool({
    client_model: model,
    fetch_policy: { max_age_seconds: LIVE_FETCH_MAX_AGE_S },
  });

  const { output } = await generateText({
    abortSignal,
    instructions:
      "You turn questions into honest profiles, one or a few subjects scored on the same measures, for a generative UI radar chart. Never invent, estimate or recall figures from memory: every value must come from a page you extracted.",
    model,
    output: Output.object({ schema: radarChartResultSchema }),
    prepareStep: ({ stepNumber }) => {
      if (stepNumber === 0) {
        return { toolChoice: { toolName: "webSearch", type: "tool" } };
      }
      if (stepNumber === 1) {
        return { toolChoice: { toolName: "webExtract", type: "tool" } };
      }
      return stepNumber >= STEPS ? { toolChoice: "none" } : {};
    },
    prompt: researchPrompt(query),
    stopWhen: isStepCount(STEPS + 1),
    tools: {
      webExtract,
      webSearch,
    },
  });

  if (!output?.series?.length) {
    throw new RadarChartNotFoundError(query);
  }
  return toRadarChartData(query, output);
}

async function researchRadarChart(query: string): Promise<RadarChartData> {
  const abortSignal = AbortSignal.timeout(TIMEOUT_MS);
  try {
    return await researchOnce(query, abortSignal);
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
    return await researchOnce(query, abortSignal);
  }
}

/**
Research a free-text topic on the web (Parallel search + extract) and shape it into a few subjects scored on the same measures.
*/
export async function getRadarChart(topic: string): Promise<RadarChartData> {
  const query = topic.trim();
  if (!query) {
    throw new RadarChartNotFoundError(topic);
  }
  if (!process.env.PARALLEL_API_KEY) {
    throw new Error(
      "PARALLEL_API_KEY is missing. Add it to .env.local to load live radar charts."
    );
  }

  try {
    return await researchRadarChart(query);
  } catch (error) {
    if (error instanceof RadarChartNotFoundError) {
      throw error;
    }
    if (Error.isError(error) && /PARALLEL_API_KEY/u.test(error.message)) {
      throw error;
    }
    throw new RadarChartNotFoundError(query, { cause: error });
  }
}

import { z } from "zod";

export const RADAR_CHART_SCALES = ["number", "percent"] as const;
export type RadarChartScale = (typeof RADAR_CHART_SCALES)[number];

/**
Fewest and most spokes. Two spokes are a line; past eight the labels crowd the web.
*/
export const MIN_AXES = 3;
export const MAX_AXES = 8;

/**
Most shapes on one web. Past three the outlines tangle.
*/
export const MAX_SERIES = 3;

export interface RadarSeries {
  /**
  Who or what this shape is, e.g. "Norway".
  */
  name: string;
  /**
  One value per axis, in the axes' order. Null where the source has no figure.
  */
  values: (number | null)[];
}

export interface RadarChartData {
  /**
  The free-text topic the model (or caller) asked for.
  */
  topic: string;
  /**
  What the values measure, e.g. "Score (0–10)" or "Benchmark accuracy".
  */
  label: string;
  scale: RadarChartScale;
  /**
  The top of the scale when it has one (10 for a 0–10 index, 100 for percent scores), or null to fit the largest value.
  */
  max: number | null;
  /**
  The measures around the web, e.g. "Income" or "Safety".
  */
  axes: string[];
  series: RadarSeries[];
  /**
  Unix time in milliseconds of when the figures were looked up.
  */
  asOf: number;
  /**
  True when this is generated data, not live figures.
  */
  fake: boolean;
  /**
  Optional attribution for thinking-step sources.
  */
  sourceHref?: string;
  sourceLabel?: string;
}

/**
Structured answer the research model must return after searching the web.
*/
export const radarChartResultSchema = z.object({
  axes: z
    .array(z.string())
    .min(MIN_AXES)
    .describe(
      `The measures, ${MIN_AXES}–${MAX_AXES}, each 1–2 words, e.g. "Income", "Safety", "Health".`
    ),
  label: z
    .string()
    .describe(
      'What the values measure in 1–4 words, with the scale in brackets when it has one, e.g. "Score (0–10)", "Accuracy" or "Daily value". No serving sizes, sources or notes.'
    ),
  max: z
    .number()
    .nullable()
    .describe(
      "The top of the scale when it has one (10 for a 0–10 index, 100 for percent scores), otherwise null."
    ),
  scale: z
    .enum(RADAR_CHART_SCALES)
    .describe("percent for percentages and shares, otherwise number."),
  series: z
    .array(
      z.object({
        name: z
          .string()
          .describe(
            'Who or what is measured, 1–3 words, e.g. "Apple" or "iPhone 17 Pro". No servings, sizes or notes.'
          ),
        values: z
          .array(z.number().nullable())
          .describe(
            "One value per axis, in the axes' order, null where the source has none."
          ),
      })
    )
    .min(1)
    .describe(`The subjects compared, 1–${MAX_SERIES}.`),
  sourceHref: z
    .string()
    .nullable()
    .describe("Best source URL for the numbers, or null."),
  sourceLabel: z
    .string()
    .nullable()
    .describe("Short source name, e.g. OECD or USDA."),
});
export type RadarChartResult = z.infer<typeof radarChartResultSchema>;

function niceCeiling(value: number): number {
  if (value <= 0) {
    return 1;
  }
  const magnitude = 10 ** Math.floor(Math.log10(value));
  const steps = [1, 2, 2.5, 5, 10];
  const step = steps.find((candidate) => candidate * magnitude >= value) ?? 10;
  return step * magnitude;
}

/**
The value at the web's outer ring: the scale's own top when it has one and nothing goes past it, otherwise a round number just above the largest value.
*/
export function radarCeiling(data: RadarChartData): number {
  const largest = Math.max(
    0,
    ...data.series.flatMap((series) =>
      series.values.filter((value) => value !== null)
    )
  );
  return data.max && data.max >= largest ? data.max : niceCeiling(largest);
}

const DECIMAL = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });

export function formatRadarValue(
  value: number,
  scale: RadarChartScale
): string {
  return scale === "percent"
    ? `${DECIMAL.format(value)}%`
    : DECIMAL.format(value);
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeRadarChart(data: RadarChartData): string {
  const series = data.series.map((entry) => {
    const values = data.axes.map((axis, index) => {
      const value = entry.values[index];
      return `${axis} ${value === null || value === undefined ? "no figure" : formatRadarValue(value, data.scale)}`;
    });
    return `${entry.name}: ${values.join(", ")}`;
  });
  return `${data.label}. ${series.join("; ")}.`;
}

